import java.util.*;

class Solution {
  public String shortestSuperstring(String[] words) {
    int n = words.length, full = 1 << n;
    int[][] ov = new int[n][n];
    for (int i = 0; i < n; i++)
      for (int j = 0; j < n; j++)
        if (i != j)
          for (int k = Math.min(words[i].length(), words[j].length()); k >= 0; k--)
            if (words[i].endsWith(words[j].substring(0, k))) {
              ov[i][j] = k;
              break;
            }
    String[][] dp = new String[full][n];
    for (int i = 0; i < n; i++) dp[1 << i][i] = words[i];
    for (int mask = 1; mask < full; mask++)
      for (int last = 0; last < n; last++)
        if (dp[mask][last] != null)
          for (int nxt = 0; nxt < n; nxt++)
            if ((mask & (1 << nxt)) == 0) {
              String cand = dp[mask][last] + words[nxt].substring(ov[last][nxt]);
              int nm = mask | 1 << nxt;
              if (dp[nm][nxt] == null
                  || cand.length() < dp[nm][nxt].length()
                  || (cand.length() == dp[nm][nxt].length() && cand.compareTo(dp[nm][nxt]) < 0))
                dp[nm][nxt] = cand;
            }
    String ans = null;
    for (String s : dp[full - 1])
      if (s != null
          && (ans == null
              || s.length() < ans.length()
              || (s.length() == ans.length() && s.compareTo(ans) < 0))) ans = s;
    return ans;
  }
}
